17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
22	    @Mapping(target = "initials", expression = "java(initials(owner))")
23	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
24	    OwnerDto toOwnerDto(Owner owner);
25	
26	    Owner toOwner(OwnerDto ownerDto);
27	
28	    /** Format an owner's name as 'LastName, FirstName' for display. */
29	    default String displayName(Owner owner) {
30	        return owner.getLastName() + ", " + owner.getFirstName();
31	    }
32	
33	    /** The upper-cased first letters of firstName and lastName, dot-separated with a trailing dot. */
34	    default String initials(Owner owner) {
35	        return initial(owner.getFirstName()) + initial(owner.getLastName());
36	    }
37	
38	    private static String initial(String name) {
39	        return Character.toUpperCase(name.charAt(0)) + ".";
40	    }
41	
42	    /** The owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY is the
43	     * last two digits of the registrationDate year. */
44	    default String membershipNumber(Owner owner) {
45	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
46	            return null;
47	        }
48	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
49	    }
50	
51	    @Mapping(target = "id", ignore = true)
52	    @Mapping(target = "pets", ignore = true)
53	    @Mapping(target = "customerCode", ignore = true)
54	    @Mapping(target = "householdId", ignore = true)
55	    @Mapping(target = "namesakeCount", ignore = true)
56	    Owner toOwner(OwnerFieldsDto ownerDto);
57	
58	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
59	
60	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
61	
62	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
63	        OwnerPageDto ownerPageDto = new OwnerPageDto();
64	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
65	        ownerPageDto.setPage(ownerPage.getNumber());
66	        ownerPageDto.setSize(ownerPage.getSize());
67	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
68	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
69	        return ownerPageDto;
70	    }
71	}
